(() => {
  const clean = (s) => (s || '').replace(/\u00a0/g, ' ').trim();
  const vis = (e) => { const r = e.getBoundingClientRect(); return r.width > 2 && r.height > 2; };
  const hosts = [...document.querySelectorAll('div')].filter(e => /dialog|modal|drawer|popup/i.test((e.className||'').toString()) && vis(e));
  const d = hosts.sort((a,b)=>a.innerText.length-b.innerText.length)[0] || document;
  return {
    hostCls: (d.className||'').toString().slice(0,80),
    title: clean(d.innerText).slice(0,120),
    btns: [...d.querySelectorAll('span,a,button')].map(b => clean(b.innerText)).filter(t => t && t.length < 12).slice(0, 40),
    fields: [...d.querySelectorAll('input,textarea,[contenteditable=true]')].filter(vis).map((e,i)=>({i, ph: e.placeholder||'', val: clean(e.value||e.innerText).slice(0,60)})),
    kas: [...d.querySelectorAll('[ka]')].map(e => e.getAttribute('ka') + '|' + clean(e.innerText).slice(0,8)).slice(0,40)
  };
})()
